import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address to ensure we don't hard-code an actor; the property is independent of caller
    function testFuzz_property(address caller) public {
        // Keep the domain wide: disallow the zero address only to avoid trivial address formatting issues
        vm.assume(caller != address(0));

        // Call version() from arbitrary caller to ensure behavior is independent of msg.sender
