pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz a caller address to ensure the rule holds for any caller
    function testFuzz_property(address caller) public {
        // keep caller wide but avoid zero address to ensure a realistic EOA
        vm.assume(caller != address(0));

        // call version() from the fuzzed caller
        bool ok;
        string memory v;
        // version() is external pure, so no need for value; call under caller context
        vm.prank(caller);
        try c.version() returns (string memory ret) {
            ok = true;
            v = ret;
        } catch {
            ok = false;
            v = "";
        }

        // The reference contract always returns "1.0.0" (no revert and exact string).
        // Single assertion: version() call must succeed and return "1.0.0".
        assertTrue(ok && (keccak256(bytes(v)) == keccak256(bytes("1.0.0"))));
    }
}

