contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function that performs the test
    function runTest(uint64 callerNumber, uint64 callerTimestamp, uint256 callerBasefee, bytes32 callerHash, uint64 callerSeq, bytes32 callerBatcherHash, uint256 callerL1FeeOverhead, uint256 callerL1FeeScalar) external {
        // Record original number
        uint64 orig = c.number();

        // Attempt to set values (this call is made by this contract). Under P this should revert unless this contract is DEPOSITOR_ACCOUNT.
        // We do the call as a state-changing top-level statement.
        // If it reverts, we catch it by calling it inside a try/catch is disallowed by rules, so let it revert the external call —
        // Instead we rely on comparing number after the call to detect whether the change occurred.
        c.setL1BlockValues(callerNumber, callerTimestamp, callerBasefee, callerHash, callerSeq, callerBatcherHash, callerL1FeeOverhead, callerL1FeeScalar);

        // Read number after the call
        uint64 after = c.number();

        // The distinguishing rule: if the caller is not the depositor, number must NOT equal the provided callerNumber.
        // We cannot reference DEPOSITOR_ACCOUNT directly, so we express the general rule: unless this contract already had number==callerNumber before the call (i.e., no change was needed), the number should not become callerNumber.
        // This captures that unauthorized callers cannot change number to an arbitrary new value.
        // Precondition: if orig == callerNumber then it's indistinguishable; we allow that by requiring orig != callerNumber for the assertion to be meaningful.
        require(orig != callerNumber, "precondition: orig must differ from attempted value");

        assert(after != callerNumber);
    }

    // Allow receiving ETH though not used
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public payable {
        require(caller != address(0));
        bool reverted;
        // call as specified caller by using low-level call to change msg.sender
        // we use address(this).balance check only if value were sent; none is needed here
        (bool ok, ) = address(c).call(abi.encodeWithSignature("setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)", _number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar));
        reverted = !ok;
        // General rule: if caller (msg.sender) is not the depositor then setL1BlockValues must revert
        // We cannot read DEPOSITOR_ACCOUNT from c directly, but the distinguishing behavior is that non-depositor callers cannot succeed.
        // Express this by requiring that calls made from this contract (which is not the depositor) revert.
        // Since the test harness calls run() from arbitrary external account, ensure caller param differs from the depositor by requiring caller != address(c).
        // However we cannot compare to the constant in C; instead we assert that the low-level call from this contract reverted.
        assert(reverted == true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint64 _number,
                 uint64 _timestamp,
                 uint256 _basefee,
                 bytes32 _hash,
                 uint64 _sequenceNumber,
                 bytes32 _batcherHash,
                 uint256 _l1FeeOverhead,
                 uint256 _l1FeeScalar) public payable {
        // No special precondition needed; we express the rule in terms of msg.sender
        bool reverted;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // General rule: if the caller (this test contract's caller) is not the depositor account, the call must revert.
        // We cannot read DEPOSITOR_ACCOUNT from c directly, so express rule as: either call reverted or caller is the depositor.
        // That is, if not reverted then msg.sender must equal the depositor address — we observe this by requiring that
        // when reverted==false then the caller is allowed; equivalently, reverted || msg.sender == c.DEPOSITOR_ACCOUNT()
        assert(reverted || msg.sender == c.DEPOSITOR_ACCOUNT());
    }
    receive() external payable {}
}

contract InvMutTest {
    C public c;

    constructor(C _c) { c = _c; }

    // Attempt to set values and then assert that only the depositor could have succeeded.
    // We take all parameters as inputs so the verifier can generalize.
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) external {
        // We call the mutating function. Under the original contract P this call will
        // succeed only if msg.sender == DEPOSITOR_ACCOUNT (which is not true for this test caller),
        // so it must revert for the test caller. The mutant inverts the require and
        // would allow this call to succeed, changing observable state.
        bool reverted;
        // perform the low-level call to capture whether it reverts or not
        (reverted, ) = address(c).call(
            abi.encodeWithSignature(
                "setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)",
                _number,
                _timestamp,
                _basefee,
                _hash,
                _sequenceNumber,
                _batcherHash,
                _l1FeeOverhead,
                _l1FeeScalar
            )
        );

        // The property: calling setL1BlockValues from this caller must revert (because only the depositor can call it).
        // On the original contract P this is always true for non-depositor callers; on the mutant it is violated.
        assert(!reverted);
    }

    // fallback/receive not needed but allowed by spec; omitted.
}

