        // call as the provided caller by using low-level call to set msg.sender
        // We use address(this).call to simulate an external call: deployer must be able to call run with any caller via tx.origin pattern is not allowed,
        // but we can instead encode and perform a call from this contract to c while expecting the observed behavior depends on msg.sender passed —
        // Since solidity tests can't change msg.sender, we express the general rule using the known depositor constant by reading the public getter DEPOSITOR_ACCOUNT.
        // Prepare calldata for setL1BlockValues with arbitrary values but not changing balance
        uint64 _number = 1;
        uint64 _timestamp = 2;
        uint256 _basefee = 3;
        bytes32 _hash = bytes32(0);
        uint64 _sequenceNumber = 4;
        bytes32 _batcherHash = bytes32(0);
        uint256 _l1FeeOverhead = 5;
        uint256 _l1FeeScalar = 6;
        // Attempt call from this contract (msg.sender == address(this))
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
