pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    DeployerReentrant attacker;

    function setUp() public { c = new C(); }

    // General rule: In the reference, during setL1BlockValues called by the depositor account,
    // the contract writes `hash` no later than other fields, so an external contract that is called
    // (reentrantly) from within the depositor context cannot observe a state where other fields are
    // updated but `hash` is not the provided _hash. The mutant moves `hash` assignment to the end,
    // so a reentrant observer can sometimes read an inconsistent state where other fields are updated
    // but `hash` still holds the old value.
    // We fuzz the deciding values: _number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash,
    // _l1FeeOverhead, _l1FeeScalar. The depositor address is the constant in the contract; we deploy
    // an attacker contract that will perform the observation (reentrant read) when the depositor (attacker)
    // calls setL1BlockValues.

    // The test takes fuzzed parameters (at least one required). We include several to allow the fuzzer
    // to find inputs that distinguish behavior.
    function testFuzz_property(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // Deploy the adversarial helper that will act as the depositor and reenter to read state.
        attacker = new DeployerReentrant(address(c));

        // The contract C expects the call to come from the constant DEPOSITOR_ACCOUNT.
        // We cannot change msg.sender of attacker, but we can instruct attacker to call c and
        // the contract's modifier compares msg.sender to a fixed address; so attacker must be
        // that fixed address. In tests we can impersonate that address via vm.prank.
