        // We cannot read DEPOSITOR_ACCOUNT from c (but it is public), so use c.DEPOSITOR_ACCOUNT() to compare.
        address depositor = c.DEPOSITOR_ACCOUNT();
        // If caller != depositor then reverted must be true; otherwise reverted may be false.
        // We express this as: caller == depositor || reverted
        assert(caller == depositor || reverted);
    }
    receive() external payable { }
}

